# region: gather
def gather(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: fold
def fold(xs, factor=3):
    return [v * factor for v in xs]

# region: sift
def sift(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: digest
def digest(xs):
    n = len(xs) - 1
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: shape
def shape(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return shape(digest(sift(fold(gather(raw)))))

